 order:Q('TITLE:"intra-session exercise sequence"; TITLE:"concurrent" AND (sequence OR order) AND meta-analysis; TITLE_ABS:"concurrent training" AND (same day OR separate days)','Same-session order and spacing','Eddens 2018, Gao 2023, Lee 2020 full text (R6-S04/05/06); Robineau 2016 abstract only (R6-S31).'),
 compat:Q('Prior R4/R5 retrieval re-verified: PMC8891239, PMC9474354 (hash match with ssctr-access-trace.json)','Chronic concurrent compatibility and counterevidence','Schumann 2022 and Lundberg 2022 full text re-read (R6-S07, R6-S08).'),
 taper:Q('(TITLE:"tapering" OR TITLE:"taper") AND endurance AND performance; TITLE:"longer disciplined tapers"','Taper fractions and duration','Wang 2023 and Smyth 2021 full text (R6-S14, R6-S15); many off-topic surgical "taper" hits excluded.'),
 maint:Q('TITLE:"maintaining physical performance" OR (TITLE:"minimal dose" AND exercise)','Reduced strength dose near events','Spiering 2021 abstract only (R6-S16); Nuzzo 2024 full text (R6-S17).'),
 hmrec:Q('TITLE:"half-marathon" AND TITLE_ABS:"recovery"','Post-event recovery time course','26 hits; one open-access recreational-runner study (R6-S18).'),
 detrain:Q('TITLE:"detraining" AND (systematic review OR meta-analysis); TITLE:"training cessation" AND "muscular performance"','Return after interruption','Zheng 2022 full text (R6-S19); Bosquet 2013 abstract only (R6-S20); older-adult and clinical detraining reviews excluded as non-applicable.'),
 quality:Q('(TITLE:"recreational runners" OR TITLE:"recreational athletes") AND (polarized OR "intensity distribution"); sprint AND "running economy" AND "endurance runners"','Threshold and interval work in recreational runners','Festa 2020 and Garcia-Pinillos 2017 full text (R6-S22, R6-S23); Munoz 2014 not open access, not used.'),
 talk:Q('TITLE:"talk test"','Effort-anchored intensity','36 hits, mostly cardiac rehabilitation (excluded); one healthy-population validation used (R6-S24).'),
 indiv:Q('TITLE_ABS:"individualized" AND "endurance training" AND "recreational runners"','Response-gated progression','Nuuttila 2022 full text (R6-S21).'),
 runST:Q('TITLE:"strength training" AND "distance running" AND (meta-analysis OR systematic review)','Strength for runners','Blagrove 2018 and Llanos-Lagos 2024 full text (R6-S25, R6-S34).'),
