 b.disposition=o.disposition;b.binding=o.binding;b.action=o.action??(o.disposition==='REVISE'?'MODIFY_CANDIDATE':'CONDITIONAL_OPTIONS');
 b.facts=[...b.facts.filter(f=>!/^Probe|^Probes/.test(f)).map(f=>f.replace('Policy R6-POLICY-1','Policy R6-POLICY-2').replace('Policy boundary','Policy R6-POLICY-2 boundary')),...o.facts,R2_PROBES];
