 if(o.replaceConditions)b.conditions=b.conditions.map(c=>{const k=Object.keys(o.replaceConditions).find(k=>c.startsWith(k));return k?o.replaceConditions[k]:c;});
 if(o.extraConditions)b.conditions=[...b.conditions,...o.extraConditions];
